select budget_bucket, singapore_budget from (select case when budget >= 3953000 then 'high' when budget >= 1499000 then 'mid' else 'low' end as budget_bucket, sum(case when location = 'Singapore' then budget else 0 end) as singapore_budget from departments where budget < 1369000 group by case when budget >= 3953000 then 'high' when budget >= 1499000 then 'mid' else 'low' end) as x where singapore_budget >= 47;
